import { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { Table, Button, Container, Alert } from 'react-bootstrap'
import { Link } from 'react-router-dom'

const UserListScreen = () => {
  const dispatch = useDispatch()
  const userList = useSelector(state => state.userList)
  const { loading, error, users } = userList

  useEffect(() => {
    dispatch({ type: 'USER_LIST_REQUEST' })
    // chamar api get users admin
  }, [dispatch])

  // Implementar delete handler

  return (
    <Container className="py-4">
      <h1>Usuários</h1>
      {loading ? <p>Carregando...</p> : error ? <Alert variant="danger">{error}</Alert> : (
        <Table striped bordered hover responsive>
          <thead><tr><th>ID</th><th>NOME</th><th>EMAIL</th><th>ADMIN</th><th></th></tr></thead>
          <tbody>
            {users.map(user => (
              <tr key={user._id}>
                <td>{user._id}</td>
                <td>{user.name}</td>
                <td>{user.email}</td>
                <td>{user.isAdmin ? 'Sim' : 'Não'}</td>
                <td><Button variant="light">Editar</Button> <Button variant="danger">Deletar</Button></td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </Container>
  )
}

export default UserListScreen
